<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api } from '../api';
import { filterPhotos, quotaLabel, selectedPhotoCount, submissionPayload } from '../state';
import { generateReadablePassword, loginInfoText } from '../utils/password';

const route = useRoute();
const router = useRouter();
const path = computed(() => route.path);
const jobId = computed(() => Number(path.value.match(/^\/jobs\/(\d+)/)?.[1] || 0));
const me = ref(null), jobs = ref([]), job = ref(null), photos = ref([]), summary = ref(null);
const loading = ref(true), error = ref(''), filter = ref('all'), lightbox = ref(null), note = ref('');
const mustChange = ref(false), currentPassword = ref(''), newPassword = ref('');
const phone = ref(''), otp = ref(''), loginName = ref('');
const adminPhone = ref(''), adminPassword = ref(''), adminLogged = ref(false), adminJobs = ref([]), adminJobId = ref(0), adminRole = ref(''), adminSettings = ref(null);
const adminMustChange = ref(false), adminCurrentPassword = ref(''), adminNewPassword = ref('');
const importSource = ref(''), importTask = ref(null), adminNotifications = ref([]), adminAuditLogs = ref([]);
const adminView = ref('orders'), customers = ref([]), customerQuery = ref(''), newCustomerName = ref(''), newCustomerPhone = ref(''), newCustomerPassword = ref(''), passwordCard = ref(null), passwordCopied = ref(false), templates = ref([]), newJobTitle = ref(''), newJobTemplate = ref(''), adminDetailTab = ref('summary'), adminSelectors = ref([]), adminPhotos = ref([]), adminComments = ref([]);
const isAdmin = computed(() => path.value.startsWith('/admin'));
const isSelectedPage = computed(() => /^\/jobs\/\d+\/selected$/.test(path.value));
const selectedTab = ref('mine'), selectedPhotos = ref([]), packages = ref([]), wechatHint = ref(false), pollTimer = ref(null);
async function loadSelected() { const data = await api.get(`/api/client/jobs/${jobId.value}/selected?tab=${selectedTab.value}`); selectedPhotos.value = data.photos || []; wechatHint.value = Boolean(data.wechat); }
async function createPackage(scope='selected_preview') { try { const result = await api.post(`/api/client/jobs/${jobId.value}/packages`, { scope }); packages.value.unshift(result.package); pollPackages(); } catch (e) { error.value = e.message; } }
async function pollPackages() { if (document.hidden || !packages.value.length) return; for (const item of packages.value.filter(p => p.status === 'pending')) { const data = await api.get(`/api/client/jobs/${jobId.value}/packages/${item.id}`); Object.assign(item, data.package); } }
function selectedNavigate(tab) { selectedTab.value = tab; loadSelected(); }

const selectedCount = computed(() => selectedPhotoCount({ quota: job.value?.quota, photos: photos.value }));
const quota = computed(() => quotaLabel(selectedCount.value, job.value?.quota?.retouch || 20));
const shownPhotos = computed(() => filterPhotos(photos.value, filter.value));

async function loadClient() {
  loading.value = true;
  try {
    const identity = await api.get('/api/auth/me'); me.value = identity.actor;
    if (identity.actor?.must_change_password) { mustChange.value = true; return; }
    const list = await api.get('/api/client/jobs'); jobs.value = list.jobs || [];
    const selectedJobId = jobId.value || jobs.value[0]?.id;
    if (!selectedJobId) { me.value = identity.actor; return; }
    const data = await api.get(`/api/client/jobs/${selectedJobId}`); me.value = { ...(data.me || {}), ...(identity.actor || {}) }; job.value = { ...data.job, quota: data.quota, selectors: data.selectors, items: data.items, original_download_scope: data.download?.original_download_scope || data.job?.original_download_scope };
    photos.value = data.photos || []; error.value = '';
  } catch (e) { error.value = e.message || '请先登录'; } finally { loading.value = false; }
}
async function loadAdmin() {
  loading.value = true;
  try {
    const identity = await api.get('/api/auth/me');
    if (!identity.actor || identity.actor.actor_type !== 'staff') throw new Error('请先登录后台');
    adminRole.value = identity.actor.role || '';
    if (identity.actor.must_change_password) { adminMustChange.value = true; adminLogged.value = false; return; }
    adminMustChange.value = false;
    adminLogged.value = true;
    const list = await api.get('/api/admin/jobs'); adminJobs.value = list.jobs || [];
    adminJobId.value = adminJobId.value || adminJobs.value[0]?.id || 0;
    if (adminJobId.value) summary.value = await api.get(`/api/admin/jobs/${adminJobId.value}/summary`);
    error.value = '';
  } catch (e) { adminLogged.value = false; error.value = e.message || '后台暂不可用'; } finally { loading.value = false; }
}
async function selectAdminJob(id) { adminJobId.value = Number(id); if (adminJobId.value) { summary.value = await api.get(`/api/admin/jobs/${adminJobId.value}/summary`); await loadAdminExtras(); } }
async function loadAdminExtras() { if (!adminJobId.value) return; try { const [notifications, logs, selectors, photos, comments] = await Promise.all([api.get(`/api/admin/jobs/${adminJobId.value}/notifications`), api.get(`/api/admin/audit-logs?job_id=${adminJobId.value}`), api.get(`/api/admin/jobs/${adminJobId.value}/selectors`), api.get(`/api/admin/jobs/${adminJobId.value}/photos`), api.get(`/api/admin/jobs/${adminJobId.value}/comments`)]); adminNotifications.value = notifications.notifications || []; adminAuditLogs.value = logs.logs || []; adminSelectors.value = selectors.selectors || []; adminPhotos.value = photos.photos || []; adminComments.value = comments.comments || []; } catch (e) { error.value = e.message; } }
async function loadCustomers() { try { const data = await api.get(`/api/admin/customers?q=${encodeURIComponent(customerQuery.value)}`); customers.value = data.customers || []; } catch (e) { error.value = e.message; } }
async function loadAdminSettings() { try { const data = await api.get('/api/admin/settings'); adminSettings.value = data.settings; } catch (e) { error.value = e.message; } }
async function runManualBackup() { try { const data = await api.post('/api/admin/settings/backup'); adminSettings.value = data.backup; } catch (e) { error.value = e.message || '备份失败'; } }
function generateCustomerPassword() { newCustomerPassword.value = generateReadablePassword(); }
async function createCustomer() {
  const manualPassword = newCustomerPassword.value.trim();
  if (manualPassword && manualPassword.length < 8) { error.value = '密码至少 8 位'; return; }
  try {
    const result = await api.post('/api/admin/customers', { name: newCustomerName.value.trim(), phone: newCustomerPhone.value.trim(), ...(manualPassword ? { password: manualPassword } : {}) });
    passwordCard.value = { type: '客户', ...result.customer, password: result.password }; passwordCopied.value = false;
    newCustomerName.value = ''; newCustomerPhone.value = ''; newCustomerPassword.value = ''; await loadCustomers();
  } catch (e) { error.value = e.message || '创建客户失败'; }
}
async function resetCustomer(customer) { try { const result = await api.post(`/api/admin/customers/${customer.id}/reset-password`); passwordCard.value = { type: '重置', ...customer, password: result.password, url: result.url }; passwordCopied.value = false; } catch (e) { error.value = e.message; } }
async function copyPasswordCard() {
  if (!passwordCard.value) return;
  const text = loginInfoText(passwordCard.value);
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
    else { const input = document.createElement('textarea'); input.value = text; input.style.position = 'fixed'; input.style.opacity = '0'; document.body.appendChild(input); input.select(); document.execCommand('copy'); input.remove(); }
    passwordCopied.value = true;
    window.setTimeout(() => { passwordCopied.value = false; }, 2000);
  } catch { error.value = '复制失败，请手动复制登录信息'; }
}
async function toggleCustomer(customer) { try { await api.patch(`/api/admin/customers/${customer.id}`, { status: customer.status === 'active' ? 'disabled' : 'active' }); await loadCustomers(); } catch (e) { error.value = e.message; } }
async function loadTemplates() { try { const data = await api.get('/api/admin/package-templates'); templates.value = data.templates || []; } catch (e) { error.value = e.message; } }
async function createJob() { try { const result = await api.post('/api/admin/jobs', { title: newJobTitle.value.trim(), template_id: newJobTemplate.value || undefined }); newJobTitle.value = ''; await loadAdmin(); await selectAdminJob(result.job.id); adminView.value = 'orders'; } catch (e) { error.value = e.message || '创建订单失败'; } }
async function switchAdminView(view) { adminView.value = view; passwordCard.value = null; if (view === 'customers') await loadCustomers(); if (view === 'new-job') await loadTemplates(); if (view === 'settings') await loadAdminSettings(); }
async function adminAction(action, body = {}) { if (!adminJobId.value) return; try { const method = action === 'publish' ? 'patch' : 'post'; await api[method](`/api/admin/jobs/${adminJobId.value}/${action}`, body); await loadAdmin(); } catch (e) { error.value = e.message; } }
async function adminLock() { await adminAction('lock'); }
async function adminReopen() { const reason = window.prompt('请输入退回修改原因'); if (reason?.trim()) await adminAction('reopen', { reason: reason.trim() }); }
async function adminImport() { if (!importSource.value.trim()) { error.value = '请输入导入目录'; return; } try { const result = await api.post(`/api/admin/jobs/${adminJobId.value}/imports`, { source: importSource.value.trim() }); importTask.value = result.import_task; pollImport(); } catch (e) { error.value = e.message; } }
async function pollImport() { if (!importTask.value) return; try { const result = await api.get(`/api/admin/jobs/${adminJobId.value}/imports/${importTask.value.id}`); importTask.value = result.import_task; if (['pending', 'processing'].includes(importTask.value.status)) setTimeout(pollImport, 1000); } catch (e) { error.value = e.message; } }
async function adminChangePassword() { try { await api.post('/api/admin/change-password', { current_password: adminCurrentPassword.value, new_password: adminNewPassword.value }); adminMustChange.value = false; adminCurrentPassword.value = ''; adminNewPassword.value = ''; await loadAdmin(); } catch (e) { error.value = e.message || '修改密码失败'; } }
async function loadAdminAfterLogin(result) { adminMustChange.value = Boolean(result.must_change_password); if (!adminMustChange.value) await loadAdmin(); }
async function staffLogin() { try { const result = await api.post('/api/admin/login', { phone: adminPhone.value, password: adminPassword.value }); await loadAdminAfterLogin(result); } catch (e) { error.value = e.message || '后台登录失败'; } }
async function downloadAdminCsv() { if (adminJobId.value) window.location.href = `/api/admin/jobs/${adminJobId.value}/export.csv`; }
async function showAdminLogs() { await loadAdminExtras(); window.alert(`通知 ${adminNotifications.value.length} 条，审计记录 ${adminAuditLogs.value.length} 条`); }
async function login() {
  error.value = '';
  try { const result = await api.post('/api/auth/login', { phone: phone.value, password: otp.value }); mustChange.value = Boolean(result.must_change_password); await loadClient(); } catch (e) { error.value = e.message || '登录失败'; }
}
async function changePassword() { try { await api.post('/api/auth/change-password', { current_password: currentPassword.value, new_password: newPassword.value }); mustChange.value = false; await loadClient(); } catch (e) { error.value = e.message || '修改密码失败'; } }
function navigate(to) { router.push(to); }
function startPolling() { clearInterval(pollTimer.value); pollTimer.value = setInterval(() => { if (!document.hidden && isSelectedPage.value) { loadSelected(); pollPackages(); } }, 2000); }

async function toggle(photo) {
  if (job.value?.status === 'locked') return;
  try { await api.patch(`/api/client/jobs/${job.value.id}/photos/${photo.id}/selection`, { selected: !photo.selected }); photo.selected = !photo.selected; } catch (e) { error.value = e.message; }
}
async function setSlot(photo, slot) {
  try { const current = photo.slots?.find(s => s.name?.includes(slot === 'frame' ? '相框' : '摆台')); await api.patch(`/api/client/jobs/${job.value.id}/photos/${photo.id}/slot`, { slot: photo.slot === slot ? null : slot, job_item_id: current?.job_item_id }); photo.slot = photo.slot === slot ? null : slot; photo.selected = true; } catch (e) { error.value = e.message; }
}
async function saveNote() { if (!lightbox.value) return; try { await api.patch(`/api/client/jobs/${job.value.id}/photos/${lightbox.value.id}/note`, { content: note.value }); lightbox.value.my_note = note.value; } catch (e) { error.value = e.message; } }
async function submit() { try { const acceptsOverage = quota.value.over === 0 || window.confirm(`已超出套餐 ${quota.value.over} 张，加片 ¥${quota.value.amount}，到店结算。确认提交吗？`); await api.post(`/api/client/jobs/${job.value.id}/submit`, submissionPayload(quota.value, acceptsOverage)); alert('已提交，影楼确认后开始修图。'); } catch (e) { error.value = e.message; } }
async function lockJob() { return adminLock(); }
function openPhoto(photo) { lightbox.value = photo; note.value = photo.note || ''; }
function closePhoto() { lightbox.value = null; }
function keydown(e) { if (!lightbox.value) return; const index = photos.value.findIndex(p => p.id === lightbox.value.id); if (e.key === 'Escape') closePhoto(); if (e.key === 'ArrowRight') openPhoto(photos.value[Math.min(index + 1, photos.value.length - 1)]); if (e.key === 'ArrowLeft') openPhoto(photos.value[Math.max(index - 1, 0)]); if (e.key === ' ') { e.preventDefault(); toggle(lightbox.value); } }
function loadCurrentRoute() { if (isAdmin.value) loadAdmin(); else if (isSelectedPage.value) { loadClient().then(() => { loadSelected(); startPolling(); }); } else loadClient(); }
onMounted(() => { window.addEventListener('keydown', keydown); loadCurrentRoute(); });
watch(() => route.fullPath, () => { clearInterval(pollTimer.value); loadCurrentRoute(); });
onUnmounted(() => { window.removeEventListener('keydown', keydown); clearInterval(pollTimer.value); });
</script>

<template>
  <div v-if="isAdmin" class="admin-shell">
    <aside class="admin-nav"><div class="brand light">名人婚纱 <small>后台</small></div><a :class="{ active: adminView === 'orders' }" @click="switchAdminView('orders')">选片订单</a><a :class="{ active: adminView === 'new-job' }" @click="switchAdminView('new-job')">新建选片任务</a><a :class="{ active: adminView === 'customers' }" @click="switchAdminView('customers')">客户账号</a><a v-if="adminRole === 'admin'" :class="{ active: adminView === 'settings' }" @click="switchAdminView('settings')">设置</a><a v-if="adminRole === 'admin'">员工账号</a></aside>
    <main class="admin-main"><div v-if="!adminLogged && !adminMustChange && !loading" class="login-wrap"><div class="login-card"><div class="brand">名人婚纱 · 后台</div><h1>员工登录</h1><label>手机号<input v-model="adminPhone" inputmode="tel" /></label><label>密码<input v-model="adminPassword" type="password" /></label><button class="button primary full" @click="staffLogin">进入后台</button><div v-if="error" class="alert danger">{{ error }}</div></div></div><div v-if="adminMustChange" class="login-wrap"><div class="login-card"><h1>首次登录请修改密码</h1><label>当前密码<input v-model="adminCurrentPassword" type="password" /></label><label>新密码<input v-model="adminNewPassword" type="password" /></label><button class="button primary full" @click="adminChangePassword">保存新密码</button><div v-if="error" class="alert danger">{{ error }}</div></div></div><div v-if="adminLogged"><template v-if="adminView === 'customers'"><header class="page-head"><div><p class="eyebrow">后台 / 客户账号</p><h1>客户账号</h1></div><div class="actions"><input v-model="customerQuery" placeholder="搜索姓名或手机号" @keyup.enter="loadCustomers" /><button class="button ghost" @click="loadCustomers">搜索</button></div></header><section class="card"><h2>新建客户</h2><div class="inline-form"><input v-model="newCustomerName" placeholder="客户姓名" /><input v-model="newCustomerPhone" inputmode="tel" placeholder="手机号" /><input v-model="newCustomerPassword" minlength="8" autocomplete="new-password" placeholder="密码（可留空自动生成）" /><button class="button ghost" type="button" @click="generateCustomerPassword">随机生成</button><button class="button primary" @click="createCustomer">创建客户</button></div></section><section v-if="passwordCard" class="card password-card"><b>{{ passwordCard.type }}登录信息（仅显示一次）</b><strong>{{ passwordCard.password }}</strong><span>{{ passwordCard.name }} · {{ passwordCard.phone }}</span><button class="button ghost" type="button" @click="copyPasswordCard">{{ passwordCopied ? '已复制' : '复制登录信息' }}</button></section><section class="card"><div class="table-wrap"><table><thead><tr><th>客户</th><th>手机号</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="customer in customers" :key="customer.id"><td>{{ customer.name }}</td><td>{{ customer.phone }}</td><td>{{ customer.status === 'active' ? '正常' : '已停用' }}</td><td class="actions"><button class="button ghost" @click="resetCustomer(customer)">重置密码</button><button class="button ghost" @click="toggleCustomer(customer)">{{ customer.status === 'active' ? '停用' : '启用' }}</button></td></tr></tbody></table></div></section></template><template v-else-if="adminView === 'settings'"><header class="page-head"><div><p class="eyebrow">后台 / 设置</p><h1>数据与备份</h1></div><button class="button primary" @click="runManualBackup">立即备份</button></header><section class="card settings-card"><p>数据目录：<code>{{ adminSettings?.data_dir }}</code></p><p>最近备份：{{ adminSettings?.lastBackupAt || '尚无备份' }}</p><p>备份数量：{{ adminSettings?.count ?? 0 }}</p></section></template><template v-else-if="adminView === 'new-job'"><header class="page-head"><div><p class="eyebrow">后台 / 新建选片任务</p><h1>新建订单</h1></div></header><section class="card form-card"><label>订单标题<input v-model="newJobTitle" placeholder="例如：2026 春季婚纱照" /></label><label>套餐模板<select v-model="newJobTemplate"><option value="">不使用模板</option><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name }}</option></select></label><button class="button primary" @click="createJob">创建订单</button></section></template><template v-else><header class="page-head"><div><p class="eyebrow">后台 / 选片订单</p><h1>选片进度与汇总</h1><label>订单 <select :value="adminJobId" @change="selectAdminJob($event.target.value)"><option v-for="item in adminJobs" :key="item.id" :value="item.id">{{ item.title }}</option></select></label></div><div class="actions"><button class="button ghost" @click="loadAdmin">刷新</button><button class="button ghost" @click="adminReopen">退回修改</button><button class="button primary" @click="adminLock">确认并锁定</button></div></header><div v-if="error" class="alert danger">{{ error }}</div><div v-if="loading" class="loading">正在加载后台数据…</div><div v-else><section class="people"><article v-for="person in (summary?.selectors || [])" :key="person.id" class="person-card"><div class="person-top"><span class="avatar">{{ person.name?.slice(0,1) }}</span><div><b>{{ person.name }}</b><small>{{ person.permission === 'select_only' ? '仅选片' : '选片 + 提交' }}</small></div><span class="status">{{ person.submitted_at ? '已提交' : '选片中' }}</span></div><div class="person-stats">精修 <strong>{{ person.selectionCount || 0 }}</strong><span>{{ person.share_selection ? '向他人公开' : '不公开' }}</span></div></article></section><section class="card"><div class="section-head"><h2>合并结果（影楼视角 · 所有人可见）</h2><span class="over-text">精修 {{ summary?.mergedCount || 0 }} / {{ summary?.quota || 20 }}</span></div><div class="table-wrap"><table><thead><tr><th>照片</th><th>文件名</th><th v-for="person in (summary?.selectors || [])" :key="person.id">{{ person.name }}</th><th>用途</th><th>备注</th></tr></thead><tbody><tr v-for="row in (summary?.rows || [])" :key="row.id"><td><img class="table-thumb" :src="row.thumb_url" /></td><td>{{ row.filename }}</td><td v-for="person in (summary?.selectors || [])" :key="person.id" class="mark">{{ row.selectedBy?.includes(person.id) ? '✓' : '' }}</td><td>{{ row.use || '精修 · 入册' }}</td><td>{{ row.note || '—' }}</td></tr></tbody></table></div></section><section class="card admin-tools"><div class="section-head"><h2>订单操作</h2><div class="actions"><button class="button ghost" @click="adminAction('publish')">发布任务</button><button class="button ghost" @click="adminAction('remind')">提醒未提交</button><button class="button ghost" @click="adminAction('settle')">标记已结算</button><button class="button ghost" @click="downloadAdminCsv">导出 CSV</button><button class="button ghost" @click="showAdminLogs">查看通知 / 审计</button></div></div><div class="actions"><input v-model="importSource" placeholder="导入目录（相册目录名）" /><button class="button ghost" @click="adminImport">导入目录</button></div><p v-if="importTask">导入进度：{{ importTask.status }} {{ importTask.processed || 0 }}/{{ importTask.total || 0 }}<span v-if="importTask.failed">，失败 {{ importTask.failed }}</span></p><p v-if="adminNotifications.length || adminAuditLogs.length" class="muted">通知 {{ adminNotifications.length }} 条，审计日志 {{ adminAuditLogs.length }} 条</p></section></div></template></div></main>
  </div>
  <div v-else class="client-shell">
    <div v-if="!me" class="login-wrap"><div class="login-card"><div class="brand">名人婚纱</div><p class="eyebrow">ONLINE PHOTO SELECTION</p><h1>选出属于你们的<br><em>精彩瞬间</em></h1><p class="muted">从底片中选出精修照片，与家人一起完成最终选择。</p><label>手机号<input v-model="phone" inputmode="tel" /></label><label>密码<input v-model="otp" type="password" /></label><button class="button primary full" @click="login">进入选片</button><div v-if="error" class="alert danger">{{ error }}</div></div></div>
    <div v-else-if="mustChange" class="login-wrap"><div class="login-card"><h1>首次登录请修改密码</h1><label>当前密码<input v-model="currentPassword" type="password" /></label><label>新密码<input v-model="newPassword" type="password" /></label><button class="button primary full" @click="changePassword">保存新密码</button><div v-if="error" class="alert danger">{{ error }}</div></div></div>
    <template v-else-if="isSelectedPage"><header class="client-header"><div><button class="button ghost" @click="navigate(`/jobs/${jobId}`)">返回选片</button><div class="brand">名人婚纱</div><h1>我的选片</h1></div></header><main class="workspace selected-page"><div class="filters"><button v-for="item in [['mine','我选的'],['final','最终结果'],['products','相框 / 摆台']]" :key="item[0]" :class="{ selected: selectedTab === item[0] }" @click="selectedNavigate(item[0])">{{ item[1] }}</button></div><p v-if="wechatHint" class="alert">请点右上角 ··· 选择“在浏览器打开”后下载，单张图可长按保存。</p><div class="photo-grid"><article v-for="photo in selectedPhotos" :key="photo.id" class="photo-card"><img :src="photo.preview_url" :alt="photo.filename" /><div class="photo-footer"><span>{{ photo.filename }}</span><a class="button ghost" :href="photo.preview_url">下载预览</a><a v-if="job?.status === 'locked' && job?.allow_original_download && job?.original_download_scope !== 'none'" class="button ghost" :href="`/api/client/jobs/${job.id}/photos/${photo.id}/original`">下载原片</a></div></article></div><div class="download-actions"><button class="button primary" @click="createPackage('selected_preview')">打包下载水印预览</button><button v-if="job?.status === 'locked' && job?.allow_original_download && job?.original_download_scope === 'all'" class="button ghost" @click="createPackage('all_original')">下载全部原片</button><button v-else-if="job?.status === 'locked' && job?.allow_original_download && job?.original_download_scope !== 'none'" class="button ghost" @click="createPackage('selected_original')">打包下载原片</button><p v-for="item in packages" :key="item.id"><span>{{ item.status }}</span> <a v-if="item.status === 'ready'" :href="item.file_url">下载 ZIP</a></p></div></main></template><template v-else><header class="client-header"><nav><button v-for="item in jobs" :key="item.id" class="button ghost" @click="navigate(`/jobs/${item.id}`)">{{ item.title }}</button></nav><div><div class="brand">名人婚纱</div><h1>{{ job?.title || '示例 · 婚纱照' }}</h1></div><div class="deadline">截止 {{ job?.deadlineLabel || '7 天后' }}</div></header><div class="mobile-quota"><div><b>{{ quota.count }}/{{ quota.quota }}</b><small>精修照片</small></div><div><b>{{ photos.filter(p => p.slot === 'frame').length }}/1</b><small>30寸相框</small></div><div><b>{{ photos.filter(p => p.slot === 'desk').length }}/1</b><small>10寸摆台</small></div></div><div v-if="error" class="alert danger">{{ error }}</div><main class="workspace"><aside class="quota-panel"><p class="eyebrow">套餐额度</p><div class="quota-big" :class="{ over: quota.over }">{{ quota.count }} <span>/ {{ quota.quota }}</span></div><div class="progress"><i :style="{ width: Math.min(100, quota.count / quota.quota * 100) + '%' }"></i></div><p class="muted">精修照片 <b>{{ quota.quota }} 张</b></p><div v-if="quota.over" class="overage">已超出 {{ quota.over }} 张<br>加片 ¥{{ quota.amount }}，到店结算</div><div class="side-rule"></div><p class="eyebrow">一起选片</p><div v-for="person in (job?.selectors || [])" :key="person.id" class="selector-row"><span class="avatar small">{{ person.name?.slice(0,1) }}</span><span>{{ person.name }}<small>{{ person.id === me?.id ? '我' : (person.share_selection ? '已公开' : '未公开') }}</small></span><b>{{ person.selectionCount || '—' }}</b></div><label class="share"><span>让其他人看到我的选择<small>影楼始终可以看到</small></span><input type="checkbox" :checked="me.share_selection" @change="api.patch(`/api/client/jobs/${job.id}/me`, { share_selection: $event.target.checked }).then(() => loadClient())" /></label></aside><section class="photo-area"><div class="toolbar"><div class="filters"><button v-for="item in [['all','全部'],['mine','我已选'],['unpicked','未选'],['print','相框 / 摆台'],['partner','他人选的']]" :key="item[0]" :class="{ selected: filter === item[0] }" @click="filter=item[0]">{{ item[1] }} <small>{{ filterPhotos(photos,item[0]).length }}</small></button></div><span class="tip">点击照片看大图 · 右上角 ✓ 选为精修</span></div><div v-if="loading" class="loading">正在准备照片…</div><div v-else class="photo-grid"><article v-for="photo in shownPhotos" :key="photo.id" class="photo-card" :class="{ picked: photo.selected }"><div class="photo-image" @click="openPhoto(photo)"><img :src="photo.thumb_url" :alt="photo.filename" loading="lazy" /><button class="check" :aria-label="photo.selected ? '取消精修' : '选为精修'" @click.stop="toggle(photo)">{{ photo.selected ? '✓' : '' }}</button><div class="tags"><span v-if="photo.slot === 'frame'">30寸相框</span><span v-if="photo.slot === 'desk'">10寸摆台</span></div><span v-if="photo.others?.length" class="partner">{{ photo.others[0].name }}也选了</span></div><div class="photo-footer"><span>{{ photo.filename }}</span><div><button :class="{ on: photo.slot === 'frame' }" @click="setSlot(photo, 'frame')">相框</button><button :class="{ on: photo.slot === 'desk' }" @click="setSlot(photo, 'desk')">摆台</button></div></div></article></div></section></main><footer class="mobile-submit"><span>选择会自动保存<br><small>截止前可修改</small></span><button class="button dark" @click="submit">去提交</button><a v-if="job?.status === 'locked' && job?.allow_original_download && job?.original_download_scope !== 'none'" class="button ghost" href="#" @click.prevent="api.post(`/api/client/jobs/${job.id}/originals.zip`).then(d => window.location.href=d.url)">下载原片</a></footer></template>
  </div>
  <div v-if="lightbox" class="lightbox" @click.self="closePhoto"><button class="close" @click="closePhoto">×</button><button class="nav prev" @click="keydown({key:'ArrowLeft'})">‹</button><div class="lightbox-body"><img :src="lightbox.preview_url" :alt="lightbox.filename"/><div class="watermark">名人婚纱 · 预览</div></div><button class="nav next" @click="keydown({key:'ArrowRight'})">›</button><aside class="lightbox-info"><b>{{ lightbox.filename }}</b><button class="button primary" @click="toggle(lightbox)">{{ lightbox.selected ? '✓ 已选为精修' : '选为精修' }}</button><div class="slot-actions"><button :class="{ on: lightbox.slot === 'frame' }" @click="setSlot(lightbox,'frame')">相框</button><button :class="{ on: lightbox.slot === 'desk' }" @click="setSlot(lightbox,'desk')">摆台</button></div><p class="eyebrow">给修图师的备注</p><textarea v-model="note" rows="4" placeholder="例如：背景路人去掉，皮肤自然一点"></textarea><button class="button ghost full" @click="saveNote">保存备注</button></aside></div>
</template>
